//! 📸️ Handcrafted JPEG raster, frame, quantization and Huffman entities.
use crate::standards::v_jfif_1_01::subsets::document::schema::snapshot::*;
use semio_framework_os_kernel::sqlite_snapshot::{ValueError, ValueRefusalKind};

fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn work(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::WorkLimit,message)}
fn ownership(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::OwnershipLimit,message)}
fn allocation(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::AllocationFailed,message)}
fn text_error(error:ValueError)->semio_framework_diagnostic::TextError{semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))}
use std::collections::{BTreeMap,BTreeSet};
use semio_framework_os_kernel::{sqlite_snapshot::{artifact::{Cell,Projection,reconstruct_text},validate_sqlite_database_schema,SqliteDatabase,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase},ArtifactSqliteSnapshot};

fn octet(row:&SqliteRow,column:usize)->Result<u8,ValueError>{u8::try_from(row.integer(column)?).map_err(|error|invalid(error.to_string()))}
fn short(row:&SqliteRow,column:usize)->Result<u16,ValueError>{u16::try_from(row.integer(column)?).map_err(|error|invalid(error.to_string()))}
fn unsigned(row:&SqliteRow,column:usize)->Result<u32,ValueError>{u32::try_from(row.integer(column)?).map_err(|error|invalid(error.to_string()))}
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,position:usize,total:usize)->Result<(),ValueError>{if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}Ok(())}
fn identifiers<'a>(rows:impl IntoIterator<Item=&'a SqliteRow>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeSet<i64>,ValueError>{let mut keys=BTreeSet::new();for(position,row)in rows.into_iter().enumerate(){checkpoint(control,position,0)?;keys.insert(row.rowid);}Ok(keys)}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<&'a [SqliteRow],ValueError>{let rows=&database.table(table)?.rows;let mut keys=BTreeSet::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;if row.rowid<=0||row.integer(0)?!=row.rowid||!keys.insert(row.rowid){return Err(invalid(format!("{table} requires unique positive aliased identities")));}}Ok(rows)}
fn groups<'a>(database:&'a SqliteDatabase,table:&str,parents:&BTreeSet<i64>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,ValueError>{let rows=entities(database,table,control)?;let mut groups=BTreeMap::<i64,Vec<&SqliteRow>>::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let owner=row.integer(1)?;if !parents.contains(&owner){return Err(invalid(format!("{table} names an unknown owner")));}groups.entry(owner).or_default().push(row);}for rows in groups.values_mut(){let mut ordered=vec![None;rows.len()];for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error|invalid(error.to_string()))?;let slot=ordered.get_mut(ordinal).ok_or_else(||invalid("JPEG child ordinals must be dense"))?;if slot.replace(*row).is_some(){return Err(invalid("JPEG child ordinals must be unique"));}}let total=ordered.len();rows.clear();for(position,row)in ordered.into_iter().enumerate(){checkpoint(control,position,total)?;rows.push(row.ok_or_else(||invalid("JPEG child ordinals must be dense"))?);}}Ok(groups)}
fn ordered<'a>(database:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<&'a SqliteRow>,ValueError>{Ok(groups(database,table,&BTreeSet::from([1]),control)?.remove(&1).unwrap_or_default())}
fn optional<'a>(database:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Option<&'a SqliteRow>,ValueError>{let rows=entities(database,table,control)?;if rows.len()>1||rows.first().is_some_and(|row|row.rowid!=1){return Err(invalid(format!("{table} optional identity must be one")));}Ok(rows.first())}
fn channel(pixel:&[u8],index:usize)->Cell<'_>{pixel.get(index).map_or(Cell::Null,|value|Cell::Integer((*value).into()))}
fn write_rgba(out:&mut Projection<'_,'_>,pixels:&[u8])->Result<(),ValueError>{for(ordinal,pixel)in pixels.chunks(4).enumerate(){out.insert("jpg_rgba_pixel",&[Cell::Integer(1),Cell::Integer(i64::try_from(ordinal).map_err(|error|work(error.to_string()))?),channel(pixel,0),channel(pixel,1),channel(pixel,2),channel(pixel,3)])?;}Ok(())}
fn write_rgb(out:&mut Projection<'_,'_>,thumbnail:&JfifThumbnail)->Result<(),ValueError>{for(ordinal,pixel)in thumbnail.rgb_data.chunks(3).enumerate(){out.insert("jpg_thumbnail_rgb_pixel",&[Cell::Integer(1),Cell::Integer(i64::try_from(ordinal).map_err(|error|work(error.to_string()))?),channel(pixel,0),channel(pixel,1),channel(pixel,2)])?;}Ok(())}
fn read_pixels(database:&SqliteDatabase,table:&str,channels:usize,present:bool,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<u8>,ValueError>{
 let rows=ordered(database,table,control)?;if !present&&!rows.is_empty(){return Err(invalid("JPEG absent thumbnail cannot own pixel channels"));}let maximum=rows.len().checked_mul(channels).ok_or_else(||work("JPEG channel count overflow"))?;control.check_value_bytes(maximum)?;let mut pixels=Vec::new();pixels.try_reserve_exact(maximum).map_err(|_|allocation("JPEG channel allocation failed"))?;
 for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;if row.values.len()!=channels+3{return Err(invalid("JPEG pixel channel shape differs from its declared schema"));}let mut absent=false;for channel in 0..channels{if row.values[3+channel]==SqliteValue::Null{if channel==0||position+1!=rows.len(){return Err(invalid("JPEG partial channels require the last pixel entity"));}absent=true;}else{if absent{return Err(invalid("JPEG pixel channels require contiguous ownership"));}pixels.push(octet(row,3+channel)?);}}}Ok(pixels)
}
fn read_octets(rows:&[&SqliteRow],control:&mut SqliteSnapshotControl<'_>)->Result<Vec<u8>,ValueError>{let mut bytes=Vec::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;bytes.push(octet(row,3)?);}Ok(bytes)}

fn native_rows(snapshot:&JpgSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 let mut rows=1usize;let mut add=|count:usize|->Result<(),ValueError>{rows=rows.checked_add(count).ok_or_else(||work("JPEG native entity row count overflow"))?;control.check_rows(rows)};
 add(snapshot.pixels.len().div_ceil(4))?;if let Some(thumbnail)=&snapshot.jfif_thumbnail{add(1)?;add(thumbnail.rgb_data.len().div_ceil(3))?;}if let Some(frame)=&snapshot.frame{add(1)?;add(frame.components.len())?;}
 add(snapshot.quant_tables.len().checked_mul(65).ok_or_else(||work("JPEG quantization row count overflow"))?)?;
 let mut quantizers=[false;256];let mut completed=0usize;let total=snapshot.quant_tables.len().checked_add(snapshot.frame.as_ref().map_or(0,|frame|frame.components.len())).ok_or_else(||work("JPEG quantizer workload overflow"))?;
 for table in &snapshot.quant_tables{quantizers[usize::from(table.id)]=true;completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,completed,total)?;}}
 if let Some(frame)=&snapshot.frame{for component in &frame.components{quantizers[usize::from(component.quant_table_id)]=true;completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,completed,total)?;}}}
 rows=rows.checked_add(quantizers.iter().filter(|present|**present).count()).ok_or_else(||work("JPEG quantizer row count overflow"))?;control.check_rows(rows)?;
 for(position,table)in snapshot.huffman_tables.iter().enumerate(){rows=rows.checked_add(17).and_then(|rows|rows.checked_add(table.values.len())).ok_or_else(||work("JPEG Huffman row count overflow"))?;control.check_rows(rows)?;if position%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,position,snapshot.huffman_tables.len())?;}}
 for(position,segment)in snapshot.other_segments.iter().enumerate(){rows=rows.checked_add(1).and_then(|rows|rows.checked_add(segment.data.len())).ok_or_else(||work("JPEG segment row count overflow"))?;control.check_rows(rows)?;if position%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,position,snapshot.other_segments.len())?;}}
 Ok(())
}

impl ArtifactSqliteSnapshot for JpgSnapshot{
 fn encode_sqlite_snapshot_native(&self,encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{
  self.preflight_sqlite_snapshot_encoding(encoding,control)?;native_rows(self,control)?;store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),owned_text::spec_producer(),|native|owned_text::to_record_controlled(self,native),control)
 }

 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{let encoding=match payload{store::io_schema::IoPayload::Binary(_)=>semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding::Binary,store::io_schema::IoPayload::Text(_)=>semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding::Text};let snapshot=store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),owned_text::spec_producer(),owned_text::from_record_controlled,control)?;snapshot.preflight_sqlite_snapshot_encoding(encoding,control)?;Ok(snapshot)}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
  use semio_framework_os_kernel::sqlite_snapshot::artifact::NativeEncodingBound;
  let mut bound=NativeEncodingBound::new(control)?;bound.add(32768)?;bound.repeated(self.schema.len(),32)?;bound.repeated(self.pixels.len(),16)?;
  if let Some(thumbnail)=&self.jfif_thumbnail{bound.add(4096)?;bound.repeated(thumbnail.rgb_data.len(),16)?;}
  if let Some(frame)=&self.frame{bound.add(4096)?;bound.repeated(frame.components.len(),4096)?;for _ in &frame.components{bound.add(64)?;}}
  bound.repeated(self.quant_tables.len(),65536)?;for _ in &self.quant_tables{bound.add(64)?;}
  bound.repeated(self.huffman_tables.len(),24576)?;for table in &self.huffman_tables{bound.repeated(table.values.len(),16)?;}
  bound.repeated(self.other_segments.len(),4096)?;for segment in &self.other_segments{bound.repeated(segment.data.len(),16)?;}bound.finish()
 }

 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{
  control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.stdio.jpg"||dialect.standard!="jfif-1.01"||!matches!(dialect.subset.as_str(),"*"|"baseline"){return Err(store::io_schema::IoError::from_value_error(ValueError::new(ValueRefusalKind::UnsupportedOwner,format!("JPEG does not own semantic subset {}",dialect.to_coordinate()))));}if database.table("jpg_document").map_err(store::io_schema::IoError::from_value_error)?.single_row().map_err(store::io_schema::IoError::from_value_error)?.text(1).map_err(store::io_schema::IoError::from_value_error)?!=self.schema{return Err(store::io_schema::IoError::from_value_error(invalid("JPEG document schema identity disagrees with its owned snapshot")));}
  let diagnostics=if dialect.subset=="baseline"{crate::standards::v_jfif_1_01::subsets::baseline::schema::check_baseline_conformance_with(self,&mut |position,total|control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,position,total)).map_err(store::io_schema::IoError::from_value_error)?}else{Vec::new()};if diagnostics.iter().any(|diagnostic|matches!(diagnostic.severity,semio_framework_diagnostic::Severity::Error|semio_framework_diagnostic::Severity::Fatal)){Err(store::io_schema::IoError{cause:invalid("JPEG baseline conformance rejected the owned snapshot"),diagnostics})}else{Ok(store::io_schema::IoOutcome{value:(),diagnostics})}
 }
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{
  let mut out=Projection::new(Self::SQLITE_SCHEMA,control)?;let units=match self.jfif_density_units{JfifDensityUnits::Aspect=>"aspect",JfifDensityUnits::PixelsPerInch=>"pixelsPerInch",JfifDensityUnits::PixelsPerCm=>"pixelsPerCm"};out.insert("jpg_document",&[Cell::Text(&self.schema),Cell::Integer(self.width.into()),Cell::Integer(self.height.into()),self.re_encode_quality.map_or(Cell::Null,|value|Cell::Integer(value.into())),Cell::Integer(self.jfif_version.0.into()),Cell::Integer(self.jfif_version.1.into()),Cell::Text(units),Cell::Integer(self.jfif_x_density.into()),Cell::Integer(self.jfif_y_density.into()),Cell::Integer(self.sof_marker.into()),Cell::Integer(i64::from(self.arithmetic)),self.restart_interval.map_or(Cell::Null,|value|Cell::Integer(value.into()))])?;write_rgba(&mut out,&self.pixels)?;
  if let Some(thumbnail)=&self.jfif_thumbnail{out.insert("jpg_thumbnail",&[Cell::Integer(thumbnail.width.into()),Cell::Integer(thumbnail.height.into())])?;write_rgb(&mut out,thumbnail)?;}
  let mut quantizers=BTreeSet::new();for(position,table)in self.quant_tables.iter().enumerate(){if position%256==0{out.checkpoint()?;}quantizers.insert(table.id);}if let Some(frame)=&self.frame{for(position,component)in frame.components.iter().enumerate(){if position%256==0{out.checkpoint()?;}quantizers.insert(component.quant_table_id);}}for quantizer in quantizers{out.insert_key("jpg_quantizer",quantizer.into(),&[Cell::Integer(1)])?;}
  if let Some(frame)=&self.frame{out.insert("jpg_frame",&[Cell::Integer(frame.precision.into()),Cell::Integer(frame.width.into()),Cell::Integer(frame.height.into())])?;for(ordinal,component)in frame.components.iter().enumerate(){out.insert("jpg_frame_component",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(component.id.into()),Cell::Integer(component.h_sampling.into()),Cell::Integer(component.v_sampling.into()),Cell::Integer(component.quant_table_id.into())])?;}}
  for(ordinal,table)in self.quant_tables.iter().enumerate(){let id=out.insert("jpg_quantization_table",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(table.id.into()),Cell::Integer(table.precision.into())])?;for(zigzag,value)in table.values.iter().enumerate(){out.insert("jpg_quantization_coefficient",&[Cell::Integer(id),Cell::Integer(zigzag as i64),Cell::Integer((*value).into())])?;}}
  for(ordinal,table)in self.huffman_tables.iter().enumerate(){let class=match table.class{JpgHuffmanClass::Dc=>"dc",JpgHuffmanClass::Ac=>"ac"};let id=out.insert("jpg_huffman_table",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(table.id.into()),Cell::Text(class)])?;for(length,count)in table.bits.iter().enumerate(){out.insert("jpg_huffman_code_length",&[Cell::Integer(id),Cell::Integer(length as i64),Cell::Integer((*count).into())])?;}for(ordinal,symbol)in table.values.iter().enumerate(){out.insert("jpg_huffman_symbol",&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Integer((*symbol).into())])?;}}
  for(ordinal,segment)in self.other_segments.iter().enumerate(){let id=out.insert("jpg_segment",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(segment.marker.into())])?;for(ordinal,octet)in segment.data.iter().enumerate(){out.insert("jpg_segment_octet",&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Integer((*octet).into())])?;}}out.finish()
 }
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{
  validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;let document=database.table("jpg_document")?.single_row()?;if document.rowid!=1||document.integer(0)?!=1{return Err(invalid("JPEG document identity must be one"));}let width=unsigned(document,2)?;let height=unsigned(document,3)?;let pixels=read_pixels(database,"jpg_rgba_pixel",4,true,control)?;
  let thumbnail=optional(database,"jpg_thumbnail",control)?;let thumbnail_width=thumbnail.map(|row|octet(row,1)).transpose()?;let thumbnail_height=thumbnail.map(|row|octet(row,2)).transpose()?;let rgb=read_pixels(database,"jpg_thumbnail_rgb_pixel",3,thumbnail.is_some(),control)?;let jfif_thumbnail=thumbnail.map(|_|JfifThumbnail{width:thumbnail_width.unwrap(),height:thumbnail_height.unwrap(),rgb_data:rgb});
  let frame_row=optional(database,"jpg_frame",control)?;let parents=if frame_row.is_some(){BTreeSet::from([1])}else{BTreeSet::new()};let mut component_rows=groups(database,"jpg_frame_component",&parents,control)?.remove(&1).unwrap_or_default();
  let mut quantizers=BTreeSet::new();let rows=&database.table("jpg_quantizer")?.rows;for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let id=octet(row,0)?;if row.rowid!=i64::from(id)||row.integer(1)?!=1||!quantizers.insert(id){return Err(invalid("JPEG quantizer identity or document reference is invalid"));}}let mut used_quantizers=BTreeSet::new();let mut components=Vec::new();for(position,row)in component_rows.drain(..).enumerate(){checkpoint(control,position,0)?;let quant_table_id=octet(row,6)?;if !quantizers.contains(&quant_table_id){return Err(invalid("JPEG frame component references an unknown quantizer"));}used_quantizers.insert(quant_table_id);components.push(JpgFrameComponent{id:octet(row,3)?,h_sampling:octet(row,4)?,v_sampling:octet(row,5)?,quant_table_id});}let frame=frame_row.map(|row|Ok::<_,ValueError>(JpgFrameHeader{precision:octet(row,1)?,width:short(row,2)?,height:short(row,3)?,components})).transpose()?;
  let quant_rows=ordered(database,"jpg_quantization_table",control)?;let keys=identifiers(quant_rows.iter().copied(),control)?;let mut coefficients=groups(database,"jpg_quantization_coefficient",&keys,control)?;let mut quant_tables=Vec::new();for(position,row)in quant_rows.iter().enumerate(){checkpoint(control,position,quant_rows.len())?;let id=octet(row,3)?;if !quantizers.contains(&id){return Err(invalid("JPEG quantization definition references an unknown quantizer"));}used_quantizers.insert(id);let rows=coefficients.remove(&row.rowid).unwrap_or_default();if rows.len()!=64{return Err(invalid("JPEG quantization definition requires all64zigzag coefficients"));}let mut values=[0;64];for(index,row)in rows.iter().enumerate(){values[index]=short(row,3)?;}quant_tables.push(JpgQuantTable{id,precision:octet(row,4)?,values});}if quantizers!=used_quantizers{return Err(invalid("JPEG quantizer entity is not referenced by any component or definition"));}
  let huff_rows=ordered(database,"jpg_huffman_table",control)?;let keys=identifiers(huff_rows.iter().copied(),control)?;let mut lengths=groups(database,"jpg_huffman_code_length",&keys,control)?;let mut symbols=groups(database,"jpg_huffman_symbol",&keys,control)?;let mut huffman_tables=Vec::new();for(position,row)in huff_rows.iter().enumerate(){checkpoint(control,position,huff_rows.len())?;let class=match row.text(4)?{"dc"=>JpgHuffmanClass::Dc,"ac"=>JpgHuffmanClass::Ac,_=>return Err(invalid("JPEG Huffman table class must be DC or AC"))};let rows=lengths.remove(&row.rowid).unwrap_or_default();if rows.len()!=16{return Err(invalid("JPEG Huffman table requires all16code-length counts"));}let mut bits=[0;16];for(index,row)in rows.iter().enumerate(){bits[index]=octet(row,3)?;}huffman_tables.push(JpgHuffmanTable{id:octet(row,3)?,class,bits,values:read_octets(&symbols.remove(&row.rowid).unwrap_or_default(),control)?});}
  let segment_rows=ordered(database,"jpg_segment",control)?;let keys=identifiers(segment_rows.iter().copied(),control)?;let mut octets=groups(database,"jpg_segment_octet",&keys,control)?;let mut other_segments=Vec::new();for(position,row)in segment_rows.iter().enumerate(){checkpoint(control,position,segment_rows.len())?;other_segments.push(JpgSegment{marker:octet(row,3)?,data:read_octets(&octets.remove(&row.rowid).unwrap_or_default(),control)?});}
  let jfif_density_units=match document.text(7)?{"aspect"=>JfifDensityUnits::Aspect,"pixelsPerInch"=>JfifDensityUnits::PixelsPerInch,"pixelsPerCm"=>JfifDensityUnits::PixelsPerCm,_=>return Err(invalid("JPEG density unit is unknown"))};let arithmetic=match document.integer(11)?{0=>false,1=>true,_=>return Err(invalid("JPEG arithmetic flag must be boolean"))};let re_encode_quality=if matches!(document.values.get(4),Some(SqliteValue::Null)){None}else{Some(octet(document,4)?)};let restart_interval=if matches!(document.values.get(12),Some(SqliteValue::Null)){None}else{Some(short(document,12)?)};let result=Self{schema:reconstruct_text(control,document.text(1)?)?,width,height,pixels,re_encode_quality,jfif_version:(octet(document,5)?,octet(document,6)?),jfif_density_units,jfif_x_density:short(document,8)?,jfif_y_density:short(document,9)?,jfif_thumbnail,frame,sof_marker:octet(document,10)?,arithmetic,quant_tables,huffman_tables,restart_interval,other_segments};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(result)
 }
}

